import {WORLDS,nearby,countFragments,act,initialPuzzle,finish} from './journey.js';
export function createStory({getState,pause,save}){
 const $=id=>document.getElementById(id),dialog=$('story'),prompt=$('interact');let current=null;
 const close=()=>{if(dialog.open)dialog.close();current=null;pause(false);save();};
 const render=()=>{const s=getState(),w=WORLDS.find(w=>w.id===current);$('story-actions').replaceChildren();$('story-hint').hidden=true;$('story-reset').hidden=true;
 const button=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;$('story-actions').append(b);};
 if(current==='journal'){$('story-title').textContent='The street that forgot morning';$('story-text').textContent='You built a night that could not end. Five parts of your memory are waiting behind five strange doors. Find the three-stone altar in each world, recover its fragment, then bring them to the shrine at the far end of the street. The meadow, blossom valley and car remain places to rest.';$('story-status').textContent=countFragments(s)+' / 5 memories recovered';for(const world of WORLDS){const p=document.createElement('p');p.className='journal-entry';p.textContent=world.name+' - '+(s.puzzles[world.id].solved?world.fragment:'Unrecovered. Look for its named doorway on the right side of the street.');$('story-actions').append(p);}return;}
 if(current==='shrine'){$('story-title').textContent=s.ending?'A place to begin':'The last lantern';$('story-status').textContent=countFragments(s)+' / 5 memories';$('story-text').textContent=s.ending?'The lantern warms beneath your hand. Somewhere, a train begins moving. The street is still here. So are you. You do not have to stop missing what is gone to make room for what comes next. Morning arrives. You can keep exploring.':countFragments(s)<5?'Five empty sockets circle the lantern. Bring back the memories from the five named worlds. Nothing you find will erase the night. Perhaps that was never the task.':'Every socket holds a memory. For the first time, the lantern has something to burn.';if(!s.ending&&countFragments(s)===5)button('Let morning in',()=>{finish(s);save();render();});return;}
 const p=s.puzzles[w.id];$('story-title').textContent=w.name;$('story-text').textContent=p.solved?w.fragment:'The altar seems to recognize you. Three stones wait beneath its arch. Restore their pattern to recover a memory.';
 $('story-status').textContent=p.solved?'Memory recovered - '+countFragments(s)+' / 5':w.kind==='align'?'Prism turns: '+p.values.join(' / '):w.kind==='lights'?'Beacons: '+p.values.map(v=>v?'lit':'dark').join(' / '):w.kind==='balance'?'Borrowed hours: '+p.total:(p.miss?'The echo breaks. Try again. ':'')+'Notes remembered: '+p.step+' / '+(w.kind==='memory'?4:3);
 if(!p.solved){$('story-hint').hidden=false;$('clue').textContent=w.clue;$('story-reset').hidden=false;w.labels.forEach((label,i)=>button(label,()=>{act(s,w.id,i);save();render();}));}
 };
 const open=(id=nearby(getState()))=>{if(!id)return;current=id;$('story-hint').open=false;pause(true);render();if(!dialog.open)dialog.showModal();prompt.hidden=true;};
 $('story-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});$('story-reset').onclick=()=>{getState().puzzles[current]=initialPuzzle(current);save();render();};prompt.onclick=()=>open();$('journal').onclick=()=>{document.getElementById('menu').close();open('journal');};
 return {open,close,isOpen:()=>dialog.open,update:()=>{const s=getState(),id=nearby(s);prompt.hidden=!id||s.paused||dialog.open;if(id)prompt.textContent=id==='shrine'?'E - Touch the shrine':'E - Read the memory altar';$('journey-progress').textContent=s.ending?'Morning has returned.':countFragments(s)+' / 5 memories recovered';}};
}
